// 监听 Rebalance 事件，在 Rebalance 前提交 offset（避免重复消费）
consumer.subscribe(topics, new ConsumerRebalanceListener() {
    @Override
    public void onPartitionsRevoked(Collection<TopicPartition> partitions) {
        // Rebalance 前触发：提交当前进度
        consumer.commitSync(currentOffsets);
        System.out.println("Rebalance: 释放分区 " + partitions);
    }

    @Override
    public void onPartitionsAssigned(Collection<TopicPartition> partitions) {
        // Rebalance 后触发：可在此处恢复状态
        System.out.println("Rebalance: 分配到分区 " + partitions);
    }
});

// 同步 + 异步混合提交（推荐实践）
try {
    while (running) {
        ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
        for (ConsumerRecord<String, String> record : records) {
            process(record);  // 业务处理
            currentOffsets.put(
                new TopicPartition(record.topic(), record.partition()),
                new OffsetAndMetadata(record.offset() + 1)
            );
        }
        consumer.commitAsync(currentOffsets, (offsets, exception) -> {
            if (exception != null) log.error("提交失败: " + offsets, exception);
        });
    }
} finally {
    try {
        consumer.commitSync(currentOffsets);  // 关闭前同步提交，确保不丢进度
    } finally {
        consumer.close();
    }
}
